<script setup lang="ts">
import {onMounted,onBeforeUnmount} from 'vue';
import type {ApiClient,OwnedProduct} from '@kuaixie/sdk';
import {t} from '@kuaixie/i18n';
import {useProductPublishing,productImageId,type ProductImageFile} from './useProductPublishing';
const props=defineProps<{client:ApiClient}>();const p=useProductPublishing(props.client),urls=new Set<string>();
function temporary(bytes:Blob){const url=URL.createObjectURL(bytes);urls.add(url);return url}
async function preview(path:string){const id=productImageId(path);if(!id||p.imageSource(path))return;try{const bytes=await props.client.files.download(id);if(!p.sessionCurrent())return;p.setPreview(path,temporary(new Blob([bytes])))}catch{if(p.sessionCurrent())p.notice.value='productMedia.previewFailed'}}
async function edit(row:OwnedProduct){p.edit(row);await Promise.all(p.draft.value.imageUrls.map(preview))}
function removeUnused(file:ProductImageFile){void p.deleteUnused(file,async()=>window.confirm(t('productMedia.confirmDelete')))}
async function upload(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);input.value='';for(const file of files){if(p.draft.value.imageUrls.length>=9){p.notice.value='productMedia.maxImages';break}if(!['image/jpeg','image/png'].includes(file.type)||file.size>10*1024*1024){p.notice.value='productMedia.invalidFile';continue}let source='';await p.uploadImage(()=>props.client.files.upload(file,file.name,'product_image'),()=>{source=temporary(file);return source})}}
onMounted(()=>{void p.load();void p.loadCategories();void p.loadMedia()});onBeforeUnmount(()=>{for(const url of urls)URL.revokeObjectURL(url)});
</script>
<template><section class="product-publishing"><h2>{{$t('product.title')}}</h2><p>{{$t('product.help')}}</p><form @submit.prevent="p.save"><fieldset :disabled="p.busy.value"><label>{{$t('product.name')}}<input v-model="p.draft.value.name" maxlength="255" required/></label><label>{{$t('product.spec')}}<input v-model="p.draft.value.spec" maxlength="255"/></label><label>{{$t('product.region')}}<input v-model="p.draft.value.region" maxlength="64" required/></label><label>{{$t('product.price')}}<input v-model="p.draft.value.price" inputmode="decimal" required/></label><label>{{$t('product.stock')}}<input v-model="p.draft.value.stock" inputmode="numeric" required/></label><label>{{$t('product.note')}}<textarea v-model="p.draft.value.note" maxlength="1024"/></label>
<div class="category-picker"><label>{{$t('productMedia.categorySearch')}}<input v-model="p.categorySearch.value" maxlength="100"/></label><button type="button" :disabled="p.categoryLoading.value" @click="p.loadCategories(false)">{{$t('productMedia.search')}}</button><label>{{$t('productMedia.category')}}<select v-model="p.draft.value.categoryId"><option value="">{{$t('productMedia.uncategorized')}}</option><option v-if="p.draft.value.categoryId&&!p.categories.value.some(row=>String(row.id)===p.draft.value.categoryId)" :value="p.draft.value.categoryId">{{$t('productMedia.currentCategory')}} {{p.draft.value.categoryId}}</option><option v-for="row in p.categories.value" :key="String(row.id)" :value="String(row.id)">{{p.categoryLabel(row)}}</option></select></label><button v-if="p.moreCategories.value" type="button" :disabled="p.categoryLoading.value" @click="p.loadCategories(true)">{{$t('productMedia.moreCategories')}}</button></div>
<div class="product-images"><label>{{$t('productMedia.upload')}}<input type="file" accept="image/jpeg,image/png" multiple :disabled="p.draft.value.imageUrls.length>=9" @change="upload"/></label><p>{{$t('productMedia.imageHelp')}}</p><div class="image-grid"><article v-for="(path,index) in p.draft.value.imageUrls" :key="path"><img v-if="p.imageSource(path)" :src="p.imageSource(path)" :alt="$t('productMedia.imageAlt',{number:index+1})"/><span v-else>{{$t('productMedia.previewPending')}}</span><button v-if="!p.imageSource(path)" type="button" @click="preview(path)">{{$t('productMedia.preview')}}</button><button type="button" @click="p.removeImage(path)">{{$t('productMedia.remove')}}</button></article></div><details><summary>{{$t('productMedia.unusedLibrary')}}</summary><button type="button" :disabled="p.mediaLoading.value" @click="p.loadMedia()">{{$t('product.refresh')}}</button><article v-for="file in p.media.value.filter(row=>!row.consumed_at)" :key="file.id"><span>{{file.original_name||$t('productMedia.ownedImage')}}</span><img v-if="p.imageSource(file.publicPath)" :src="p.imageSource(file.publicPath)" :alt="$t('productMedia.ownedImage')"/><button v-if="!p.imageSource(file.publicPath)" type="button" @click="preview(file.publicPath)">{{$t('productMedia.preview')}}</button><button type="button" :disabled="p.draft.value.imageUrls.includes(file.publicPath)" @click="p.attachImage(file)">{{$t('productMedia.useImage')}}</button><button type="button" :disabled="p.draft.value.imageUrls.includes(file.publicPath)" @click="removeUnused(file)">{{$t('productMedia.deleteUnused')}}</button></article></details></div>
<div class="form-actions"><button>{{$t(p.editing.value?'product.saveEdit':'product.save')}}</button><button v-if="p.editing.value" type="button" @click="p.reset">{{$t('product.cancel')}}</button></div></fieldset></form><p v-if="p.notice.value" role="status">{{$t(p.notice.value)}}</p><button :disabled="p.busy.value" @click="p.load(false)">{{$t('product.refresh')}}</button><article v-for="row in p.rows.value" :key="row.id"><strong>{{row.name}}</strong><span>{{row.price}} CNY · {{$t(row.status==='on'?'product.on':'product.off')}} · {{row.stock}}</span><div><button :disabled="p.busy.value" @click="edit(row)">{{$t('product.edit')}}</button><button :disabled="p.busy.value" @click="p.toggle(row)">{{$t(row.status==='on'?'product.unlist':'product.list')}}</button></div></article><button v-if="p.more.value" :disabled="p.busy.value" @click="p.load(true)">{{$t('account.more')}}</button></section></template>
<style scoped>.product-publishing{background:var(--kx-surface,#fff);border:1px solid #e2e8f0;border-radius:18px;padding:24px;margin-bottom:24px}.product-publishing fieldset{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;border:0;padding:0}.product-publishing label{display:flex;flex-direction:column;gap:6px;font-size:14px}.product-publishing input,.product-publishing textarea,.product-publishing select{border:1px solid #cbd5e1;border-radius:8px;padding:10px;width:100%;box-sizing:border-box}.product-publishing button{padding:9px 14px;border-radius:8px;background:#0e7490;color:#fff;border:0;margin:6px 8px 6px 0}.product-publishing button:disabled{opacity:.5}.product-publishing article{padding:14px 0;border-bottom:1px solid #e2e8f0;display:flex;flex-wrap:wrap;gap:15px;align-items:center}.product-publishing p{font-size:13px;line-height:1.7;color:#64748b}.category-picker,.product-images,.form-actions{grid-column:1/-1}.image-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:10px}.image-grid article{display:grid;gap:8px}.product-images img{width:120px;height:100px;object-fit:cover;border-radius:8px}@media(max-width:600px){.product-publishing fieldset{grid-template-columns:1fr}}</style>
